const incoming = $input.first()?.json ?? {};
return [{
  json: {
    ...incoming,
    openclawRoutingContract: 'D-0015-W',
    primaryName: 'vps_canonical',
    primaryBaseUrl: 'https://ubuntu.tailc01234.ts.net',
    primaryHealthUrl: 'https://ubuntu.tailc01234.ts.net/health',
    fallbackName: 'windows_private_fallback',
    fallbackBaseUrl: 'https://asusdesktop.tailc01234.ts.net',
    fallbackHealthUrl: 'https://asusdesktop.tailc01234.ts.net/health',
    privateOnly: true
  }
}];

const base = $('Set canonical broker candidates').first().json;
const primary = $('Primary VPS OpenClaw health').first()?.json ?? {};
const fallback = $('Windows fallback OpenClaw health').first()?.json ?? {};

function statusOf(v) {
  const candidates = [
    v?.statusCode,
    v?.status,
    v?.response?.statusCode,
    v?.response?.status
  ];
  for (const c of candidates) {
    const n = Number(c);
    if (Number.isFinite(n) && n > 0) return n;
  }
  return 0;
}
function healthy(s) { return s >= 200 && s < 300; }

const primaryStatus = statusOf(primary);
const fallbackStatus = statusOf(fallback);

let selected = 'none';
let selectedBaseUrl = '';
let reason = 'NO_HEALTHY_PRIVATE_BROKER';

if (healthy(primaryStatus)) {
  selected = base.primaryName;
  selectedBaseUrl = base.primaryBaseUrl;
  reason = 'PRIMARY_HEALTHY';
} else if (healthy(fallbackStatus)) {
  selected = base.fallbackName;
  selectedBaseUrl = base.fallbackBaseUrl;
  reason = 'PRIMARY_UNAVAILABLE_FALLBACK_HEALTHY';
}

return [{
  json: {
    ...base,
    brokerSelected: selected,
    selectedBaseUrl,
    reason,
    primaryStatus,
    fallbackStatus,
    primaryHealthy: healthy(primaryStatus),
    fallbackHealthy: healthy(fallbackStatus),
    failClosed: selected === 'none',
    privateOnly: true,
    generatedAt: new Date().toISOString()
  }
}];
